//! Acceptance criteria of spec node `KRN.MZ.LIN.LINE3` (AC-1..AC-4), REQ-004 cross-check
//! against `fit.cylinder.mc@1.0.0` (`KRN.ENV.MCC.CYL`), and error paths.
//!
//! Fixtures live in `fixtures/fit/mz-line3-v1/cases.txt` (generated by exact rational
//! geometry in `fixtures/fit/make_mz_line3_fixtures.py`, CC-BY-4.0) and are embedded via
//! `include_str!` so tests pass identically on x86-64, ARM64 and `wasm32-wasip1`.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]
#![allow(clippy::result_large_err)]

use fid_fit::contract::{
    encode as encode_fit_result, Constraint, Fit, FitError, FitParams, FittedFeature, Method, PointsView, StopReason,
};
use fid_fit::mcc_cyl::fit_mcc_cylinder;
use fid_fit::mz_line3::{command_row, encode, fit_mz_line3, output_digest, Line3Mz, MzLine3Params};
use fid_kci::kci::{sha256, to_hex};
use fid_kci::{check, parse_card, CardRegistry, InputArity};
use fid_solv::cert::CertKind;
use fid_types::{Determinism, SideEffect};

const CASES: &str = include_str!("../../../fixtures/fit/mz-line3-v1/cases.txt");
const CARD: &str = include_str!("../cards/fit.line3.mz@1.0.0.toml");

fn hex(s: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(s, 16).unwrap())
}

#[derive(Debug, Clone)]
struct Case {
    name: String,
    diameter: f64,
    axis: [f64; 3],
    mcc: bool,
    xyz: Vec<f64>,
}

fn cases() -> Vec<Case> {
    let mut out = Vec::new();
    let mut cur: Option<Case> = None;
    for raw in CASES.lines() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let toks: Vec<&str> = line.split_whitespace().collect();
        match toks[0] {
            "case" => {
                cur = Some(Case {
                    name: toks[1].to_string(),
                    diameter: 0.0,
                    axis: [0.0; 3],
                    mcc: false,
                    xyz: Vec::new(),
                });
            }
            "diameter" => cur.as_mut().unwrap().diameter = hex(toks[1]),
            "axis" => cur.as_mut().unwrap().axis = [hex(toks[1]), hex(toks[2]), hex(toks[3])],
            "mcc" => cur.as_mut().unwrap().mcc = toks[1] == "true",
            "p" => cur.as_mut().unwrap().xyz.extend_from_slice(&[hex(toks[1]), hex(toks[2]), hex(toks[3])]),
            "end" => out.push(cur.take().unwrap()),
            other => panic!("unexpected token {other}"),
        }
    }
    out
}

/// AC-1, AC-2, REQ-004 & AC-4: seeded 5-contact bent/twisted 3D lines (near origin and 1 km
/// from origin, including points directly on the axis) match analytic diameters within 1e-10 m,
/// cross-check with `fit.cylinder.mc@1.0.0` (`KRN.ENV.MCC.CYL`) within 1e-9 m, replay IDENTICAL,
/// and match the cross-target D0 digest pin.
#[test]
fn ac1_ac2_req004_seeded_mz_line3_and_mcc_cross_check() {
    let all = cases();
    assert_eq!(all.len(), 3);
    let mut digest_stream = Vec::new();

    for c in &all {
        let pts = PointsView::new(&c.xyz, None).unwrap();
        let params = FitParams::new(Method::MinimumZone);
        let extra = MzLine3Params::default();

        let res = fit_mz_line3(&pts, &params, &extra).unwrap();
        assert_eq!(res.algorithm.to_string(), "fit.line3.mz@1.0.0");
        assert!(
            (res.diameter - c.diameter).abs() <= 1e-10,
            "{}: diameter got={} expected={} diff={:e}",
            c.name,
            res.diameter,
            c.diameter,
            (res.diameter - c.diameter).abs()
        );
        let FittedFeature::Line3 { d, .. } = res.feature else {
            panic!("{}: expected Line3", c.name);
        };
        let dot = (d[0] * c.axis[0] + d[1] * c.axis[1] + d[2] * c.axis[2]).abs();
        assert!((1.0 - dot).abs() <= 1e-9, "{}: axis mismatch got={d:?} exp={:?}", c.name, c.axis);

        let cert = res.certificate.as_ref().expect("certified 3D line must carry certificate");
        assert_eq!(cert.kind(), CertKind::Zone);
        assert_eq!(cert.active_set().len(), 5, "{}: expected 5 contacts", c.name);
        assert_eq!(res.critical_points.len(), 5);
        assert!(res.max_violation <= 1e-11);

        // Fit trait parity & exact replay IDENTICAL.
        let fr = Line3Mz.fit(&pts, &params, None).unwrap();
        assert_eq!(fr.feature, res.feature);
        assert_eq!(fr.residuals, res.residuals);
        assert_eq!(fr.diagnostics.stop, StopReason::Exchange);
        assert!(fr.certificate.is_some());
        let fr2 = Line3Mz.fit(&pts, &params, None).unwrap();
        assert_eq!(encode_fit_result(&fr).unwrap(), encode_fit_result(&fr2).unwrap());

        let d1 = output_digest(&res).unwrap();
        let res2 = fit_mz_line3(&pts, &params, &extra).unwrap();
        let d2 = output_digest(&res2).unwrap();
        assert_eq!(d1, d2, "{}: exact replay digest mismatch", c.name);
        assert_eq!(encode(&res).unwrap(), encode(&res2).unwrap());
        digest_stream.extend_from_slice(d1.as_str().as_bytes());
        digest_stream.push(b'\n');

        // REQ-KRN.MZ.LIN.LINE3-004: cross-check with fit.cylinder.mc@1.0.0 (fail > 1e-9 m).
        if c.mcc {
            let mcc_params = FitParams::new(Method::MinimumCircumscribed);
            let mcc = fit_mcc_cylinder(&pts, &mcc_params, Some(0)).unwrap();
            let FittedFeature::Cylinder { r: mcc_r, .. } = mcc.feature else {
                panic!("expected Cylinder");
            };
            let mcc_diam = 2.0 * mcc_r;
            let diff = (res.diameter - mcc_diam).abs();
            assert!(
                diff <= 1e-9,
                "{}: REQ-004 MCC cross-check failed: line3.diameter={} mcc.diameter={} diff={:e}",
                c.name,
                res.diameter,
                mcc_diam,
                diff
            );
        }
    }

    let combined = to_hex(&sha256(&digest_stream));
    // Cross-target D0 digest pin verified on x86-64, ARM64 and wasm32 (AC-1/AC-4).
    const OUTPUT_PIN: &str = "9f3380813285ac13a85e651a85778f9c95026ef541fe866845ea06cf5836f7a7";
    assert_eq!(combined, OUTPUT_PIN, "cross-target D0 digest mismatch");
}

/// AC-3 (error path): disc-like point cloud -> `IllConditioned` (aspect guard / eig ratio),
/// both for an isotropic disc and an elliptical disc where LS line succeeds but aspect fails.
#[test]
fn ac3_disc_like_cloud_returns_ill_conditioned() {
    let params = FitParams::new(Method::MinimumZone);
    let extra = MzLine3Params::default();

    // 1. Isotropic disc in XY (r = 100 mm, thickness = 0.1 mm): eig ratio fails in LS start.
    let mut iso_disc = Vec::new();
    for k in 0..16 {
        let th = (k as f64) * core::f64::consts::TAU / 16.0;
        let z = if k % 2 == 0 { 5e-5 } else { -5e-5 };
        iso_disc.extend_from_slice(&[0.1 * th.cos(), 0.1 * th.sin(), z]);
    }
    let pv_iso = PointsView::new(&iso_disc, None).unwrap();
    let err_iso = fit_mz_line3(&pv_iso, &params, &extra).unwrap_err();
    assert!(matches!(err_iso, FitError::IllConditioned { .. }), "expected IllConditioned, got {err_iso:?}");

    // 2. Elliptical pancake (half-axes X=0.05, Y=0.04, Z=0.001): eig ratio = (0.04/0.05)^2 = 0.64 < 0.9
    //    so LS line succeeds, and our explicit aspect guard catches axial/radial = 2.5 < aspect_min=4.0!
    let mut ellip_disc = Vec::new();
    for k in 0..16 {
        let th = (k as f64) * core::f64::consts::TAU / 16.0;
        let z = if k % 2 == 0 { 0.001 } else { -0.001 };
        ellip_disc.extend_from_slice(&[0.05 * th.cos(), 0.04 * th.sin(), z]);
    }
    let pv_ell = PointsView::new(&ellip_disc, None).unwrap();
    let strict_extra = MzLine3Params { aspect_min: 4.0, seq: None };
    let err_ell = fit_mz_line3(&pv_ell, &params, &strict_extra).unwrap_err();
    assert!(matches!(err_ell, FitError::IllConditioned { .. }), "expected IllConditioned, got {err_ell:?}");
}

/// Exact collinear 3D line (zero diameter) and fixed-direction exact SOCP line.
#[test]
fn collinear_zero_diameter_and_fixed_direction_socp() {
    let params = FitParams::new(Method::MinimumZone);
    let extra = MzLine3Params::default();

    // Exact collinear dyadic points at 1 km -> diameter == 0.0.
    let col = [1000.0, 0.0, -0.0625, 1000.0, 0.0, 0.0, 1000.0, 0.0, 0.0625];
    let pv_col = PointsView::new(&col, None).unwrap();
    let res_col = fit_mz_line3(&pv_col, &params, &extra).unwrap();
    assert_eq!(res_col.diameter, 0.0);
    assert!(!res_col.local_optimum_only);

    // Fixed direction along Z: equilateral triangle of radius 0.004 m -> diameter == 0.008 m.
    let r = 0.004_f64;
    let mut tri = Vec::new();
    for k in 0..3 {
        let th = (k as f64) * core::f64::consts::TAU / 3.0;
        tri.extend_from_slice(&[r * th.cos(), r * th.sin(), (k as f64) * 0.05]);
    }
    let pv_tri = PointsView::new(&tri, None).unwrap();
    let mut p_fixed = FitParams::new(Method::MinimumZone);
    p_fixed.constraints.push(Constraint::FixedAxisDirection([0.0, 0.0, 1.0]));
    let res_fix = fit_mz_line3(&pv_tri, &p_fixed, &extra).unwrap();
    assert!((res_fix.diameter - 2.0 * r).abs() <= 1e-12, "got {}", res_fix.diameter);
    assert!(!res_fix.local_optimum_only);
}

/// AC-4: command row (`fit.mz_line3@1`) validates cleanly and spec card (`fit.line3.mz@1.0.0`)
/// passes `fid_kci::check`.
#[test]
fn ac4_command_row_and_spec_card_pass() {
    let row = command_row().unwrap();
    assert_eq!(row.command.as_str(), "fit.mz_line3@1");
    assert_eq!(row.side_effect, SideEffect::W2);
    assert_eq!(row.dry_run, SideEffect::R1);
    assert_eq!(row.determinism, Determinism::D0);
    assert!(row.validate().is_ok(), "invalid row: {:?}", row.validate());
    assert!(!row.to_json().unwrap().is_empty());

    let card = parse_card(CARD).unwrap();
    assert_eq!(card.determinism, "D0");
    assert_eq!(card.input_arity, InputArity::exactly(1));
    let ids = [Line3Mz.algorithm_id()];
    let card_ids = [card.id.clone()];
    let report = check(&ids, &card_ids);
    assert!(report.is_clean(), "{report:?}");
    CardRegistry::new(vec![card]).unwrap();
}
